package com.commercecore.wishlist;
import com.commercecore.product.*;import com.commercecore.user.UserAccount;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="wishlist_items")public class WishlistItem{@Id@GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private UserAccount user;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="product_id",nullable=false)private Product product;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="variant_id")private ProductVariant variant;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt;protected WishlistItem(){}public WishlistItem(UserAccount u,Product p,ProductVariant v){user=u;product=p;variant=v;}@PrePersist void create(){createdAt=Instant.now();}public UUID getId(){return id;}public UserAccount getUser(){return user;}public Product getProduct(){return product;}public ProductVariant getVariant(){return variant;}public Instant getCreatedAt(){return createdAt;}}
